// e2e/specs/mfg/rpt.spec.ts - Reports & export (TC-RPT-001..009): the 25 seeded reports, filters, CSV / PDF export, field-level security of exports,
// scheduled e-mail delivery (gap), totals vs lists, role scoping, empty result handling.
// Reports are generated by name from org-wide data (mfg-report-builders.ts); seeded reports have no owner, so a Sales Executive (own-record scope) sees none
// of them (D-121). Cases that need a report for another role use a THROWAWAY report row (same name, so the same builder runs) that is archived afterwards.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { expect, test, type Locator, type Page } from "@playwright/test";
import { authFile, MFG_USERS } from "../../fixtures/mfgUsers";
import { apiAs, type ApiClient, build, ok } from "../../mfg/api";
import { tc } from "../../mfg/caseTest";
import { reportScheduleRows, restrictedRolesOf } from "../../mfg/db";
import { assertNoProviderCredentials } from "../../mfg/envGuard";
import { knownDefect } from "../../mfg/guards";
import { pdfText } from "../../mfg/pdf";
import { uniqueTag } from "../../mfg/tag";

type Rec = Record<string, unknown>;
interface Table { columns: { key: string; label: string; type: string }[]; rows: Rec[]; totals?: Record<string, number> }
interface ReportRow { id: string; name: string; category: string; ownerId: string | null; scheduleFrequency: string }

const PIPELINE = "Pipeline & weighted pipeline";
const LEAD_SOURCE = "Lead source & campaign performance";

test.beforeAll(() => {
  assertNoProviderCredentials(); // scheduled e-mail delivery (RPT-006) must never reach SES
});

/** The 25 report names as seeded (REPORT_DEFAULTS in manufacturing-defaults.data.ts) - read from the source so a rename fails here first (drift guard). */
const seededNames = (): string[] => {
  const src = readFileSync(resolve(__dirname, "../../../backend/src/modules/manufacturing-defaults/manufacturing-defaults.data.ts"), "utf8");
  const start = src.indexOf("export const REPORT_DEFAULTS");
  const end = src.indexOf("\n];", start);
  if (start < 0 || end < 0) throw new Error("REPORT_DEFAULTS not found in manufacturing-defaults.data.ts (moved? update the drift guard)");
  return [...src.slice(start, end).matchAll(/name: '([^']+)'/g)].map((m) => m[1] as string);
};
const reportsOf = async (api: ApiClient): Promise<ReportRow[]> => (ok(await api.get("/modules/reports?limit=100"), "list reports").body.data ?? []) as unknown as ReportRow[];
const reportNamed = async (api: ApiClient, name: string): Promise<ReportRow> => {
  const r = (await reportsOf(api)).find((x) => x.name === name);
  if (!r) throw new Error(`precondition: report '${name}' is seeded for the E2E org`);
  return r;
};
const tableOf = async (api: ApiClient, id: string): Promise<Table> => ok(await api.get(`/modules/reports/${id}/table/data`), "run report").body as unknown as Table;
const newReport = async (api: ApiClient, name: string, over: Rec = {}): Promise<string> => {
  const r = ok(await api.post("/modules/reports", { name, category: "Pipeline", ...over }), `create throwaway report '${name}'`);
  return r.body.id as string;
};
const archiveQuietly = async (key: string, ids: string[]): Promise<void> => {
  const director = await apiAs("director");
  for (const id of ids) {
    try {
      await director.post(`/modules/${key}/${id}/archive`);
    } catch {
      // cleanup only
    }
  }
};
const raw = async (api: ApiClient, path: string): Promise<{ status: number; text: string; buffer: Buffer; type: string }> => {
  const res = await fetch(`http://localhost:3001/api/v1${path}`, { headers: { authorization: `Bearer ${api.token}` } });
  const buffer = Buffer.from(await res.arrayBuffer());
  return { status: res.status, text: buffer.toString("utf8"), buffer, type: res.headers.get("content-type") ?? "" };
};
/** Opens a report and waits for its settled state: a table header or the empty state; never the error line. */
const openReport = async (page: Page, id: string, name: string): Promise<void> => {
  await page.goto(`/reports/${id}`);
  await expect(page.getByRole("heading", { name, exact: true })).toBeVisible();
  await expect(page.locator("table thead th").first().or(page.getByText("No data yet."))).toBeVisible();
  await expect(page.getByText("Couldn't load this table.")).toHaveCount(0);
};
const download = async (page: Page, button: string): Promise<{ name: string; body: Buffer }> => {
  // Only the main + one secondary action are header buttons; the rest are in the "⋯" menu.
  const target = page.getByRole("button", { name: button, exact: true });
  if (!(await target.first().isVisible())) await page.getByRole("button", { name: "More actions", exact: true }).click();
  const [dl] = await Promise.all([page.waitForEvent("download"), target.first().click()]);
  const path = await dl.path();
  return { name: dl.suggestedFilename(), body: readFileSync(path) };
};
/** RFC-4180-style parser (quoted fields, doubled quotes, commas / newlines inside quotes): rows of fields. */
const parseCsv = (csv: string): string[][] => {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = "";
  let quoted = false;
  for (let i = 0; i < csv.length; i += 1) {
    const c = csv.charAt(i);
    if (quoted) {
      if (c === '"' && csv.charAt(i + 1) === '"') { field += '"'; i += 1; } else if (c === '"') quoted = false; else field += c;
    } else if (c === '"') quoted = true;
    else if (c === ",") { row.push(field); field = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && csv.charAt(i + 1) === "\n") i += 1;
      row.push(field); rows.push(row); row = []; field = "";
    } else field += c;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows;
};
const stageProbability = (stage: string): number => {
  const src = readFileSync(resolve(__dirname, "../../../backend/src/modules/manufacturing-defaults/manufacturing-defaults.data.ts"), "utf8");
  const m = new RegExp(`\\['${stage}', (\\d+)\\]`).exec(src);
  if (!m) throw new Error(`stage '${stage}' not found in STAGES (manufacturing-defaults.data.ts)`);
  return Number(m[1]);
};
const userIdOf = async (api: ApiClient): Promise<string> => {
  const payload = JSON.parse(Buffer.from(api.token.split(".")[1] ?? "", "base64url").toString("utf8")) as { sub?: string; id?: string };
  const id = payload.sub ?? payload.id;
  if (!id) throw new Error("no user id in the JWT");
  return id;
};
const bodyRows = (page: Page): Locator => page.locator("table tbody tr");
const stageCounts = (t: Table): Record<string, number> => Object.fromEntries(t.rows.map((r) => [r.stage as string, r.count as number]));

test.describe("Reports - Director", () => {
  test.use({ storageState: authFile("director") });

  tc("TC-RPT-001", async ({ page }) => {
    test.setTimeout(180_000);
    const director = await apiAs("director");
    const names = seededNames();
    expect(names, "25 standard reports in the seed constants").toHaveLength(25);
    const reports = await reportsOf(director);
    expect(reports.map((r) => r.name).sort(), "the Reports list shows exactly the 25 seeded names").toEqual([...names].sort());

    for (const report of reports) {
      const table = await tableOf(director, report.id);
      expect(table.columns.length, `'${report.name}' has columns`).toBeGreaterThan(0);
      expect(JSON.stringify(table.rows[0] ?? {}), `'${report.name}' is generated, not the 'not yet implemented' placeholder`).not.toContain("not yet implemented");
      await openReport(page, report.id, report.name);
      if (table.rows.length > 0) {
        await expect(page.locator("table thead th"), `'${report.name}' column headers`).toHaveCount(table.columns.length);
        await expect(bodyRows(page), `'${report.name}' rows`).toHaveCount(table.rows.length + (table.totals ? 1 : 0));
      } else {
        await expect(page.getByText("No data yet."), `'${report.name}' has no rows: empty state`).toBeVisible();
      }
    }
    // the list screen itself loads (first page of the 20-row list)
    await page.goto("/reports");
    await expect(page.getByText(names[0] as string, { exact: true }).first()).toBeVisible();
  });

  tc("TC-RPT-007", async () => {
    const director = await apiAs("director");
    const sales = await apiAs("salesExec1");
    const report = await reportNamed(director, PIPELINE);
    const openDeals = async (): Promise<{ count: number; value: number; byStage: Record<string, number> }> => {
      const byStage: Record<string, number> = {};
      let value = 0;
      let count = 0;
      for (let page = 1; ; page += 1) {
        const r = ok(await director.get(`/modules/opps?limit=100&page=${page}`), "list opportunities").body as { data?: Rec[]; pages?: number };
        for (const o of r.data ?? []) {
          if (o.stage === "Won" || o.stage === "Lost") continue;
          count += 1;
          value += o.value as number;
          byStage[o.stage as string] = (byStage[o.stage as string] ?? 0) + 1;
        }
        if (page >= (r.pages ?? 1)) break;
      }
      return { count, value, byStage };
    };
    const opps: string[] = [];
    try {
      const beforeReport = await tableOf(director, report.id);
      const account = await build.account(sales);
      opps.push((await build.opportunity(sales, account.id, { value: 1_000_000, stage: "Costing" })).id);
      opps.push((await build.opportunity(sales, account.id, { value: 2_000_000, stage: "Negotiation" })).id);
      const afterReport = await tableOf(director, report.id);
      expect((afterReport.totals?.value ?? NaN) - (beforeReport.totals?.value ?? NaN), "report value total grows by Rs 30 L").toBe(3_000_000);
      expect((afterReport.totals?.weighted ?? NaN) - (beforeReport.totals?.weighted ?? NaN), "report weighted total grows by 4.5 L + 12 L").toBe(1_650_000);
      // same data in the Opportunities list: counts per stage and the value total (open deals) are equal
      const list = await openDeals();
      expect(list.byStage, "deals per stage: report = list").toEqual(stageCounts(afterReport));
      expect(list.count, "open deal count: report = list").toBe(afterReport.rows.reduce((s, r) => s + (r.count as number), 0));
      expect(list.value, "pipeline value: report total = sum of the list").toBe(afterReport.totals?.value);
      for (const row of afterReport.rows) {
        expect(row.weighted, `weighted value of '${row.stage as string}' = value x stage probability`).toBe(Math.round(((row.value as number) * stageProbability(row.stage as string)) / 100));
      }
    } finally {
      await archiveQuietly("opps", opps);
    }
  });
});

test.describe("Reports - Sales Manager", () => {
  test.use({ storageState: authFile("salesManager") });

  tc("TC-RPT-002", async ({ page }) => {
    const manager = await apiAs("salesManager");
    const filters = { dateRange: "This month", team: "West team", region: "West", source: "Google Ads" };
    const unfiltered = await newReport(manager, LEAD_SOURCE, { category: "Leads" });
    const filtered = await newReport(manager, LEAD_SOURCE, { category: "Leads", ...filters });
    try {
      // The Filters tab shows the saved filter fields (what the registry offers: date range, team, region, product, industry, source; there is no customer filter).
      await openReport(page, filtered, LEAD_SOURCE);
      await page.getByRole("tab", { name: "Filters" }).click();
      for (const label of ["Date range", "Owner / team", "Region", "Product", "Industry", "Source"]) await expect(page.getByText(label, { exact: true }).first(), `filter field '${label}'`).toBeVisible();
      await expect(page.getByText("West", { exact: true }).first()).toBeVisible();
      await expect(page.getByText("Google Ads", { exact: true }).first()).toBeVisible();

      // Spec: applying a filter narrows the rows (and totals), clearing restores them. The report generator takes no filters at all (D-118): rows are identical,
      // for the saved filters and for query-string filters alike.
      const all = await tableOf(manager, unfiltered);
      const saved = await tableOf(manager, filtered);
      expect(all.rows.length, "the unfiltered report has several sources").toBeGreaterThan(1);
      const viaQuery = ok(await manager.get(`/modules/reports/${unfiltered}/table/data?source=${encodeURIComponent("Google Ads")}`), "run report with a source filter").body as unknown as Table;
      await knownDefect(test.info(), "D-118", async () => {
        expect(saved.rows.map((r) => r.source), "report saved with source = Google Ads lists only that source").toEqual(["Google Ads"]);
        expect(viaQuery.rows.map((r) => r.source), "report run with ?source=Google Ads lists only that source").toEqual(["Google Ads"]);
      });
      // The product / industry filter fields are keyed fproduct / findustry in the UI but product / industry in the API: saving them is refused (D-119).
      const patch = await manager.patch(`/modules/reports/${filtered}`, { fproduct: "Weighbridge" });
      await knownDefect(test.info(), "D-119", async () => {
        expect(patch.status, "saving the Product filter").toBe(200);
      });
      if (patch.status !== 200) expect([patch.status, JSON.stringify(patch.body.message)], "current: the Product filter cannot be saved (remove with D-119)").toEqual([400, expect.stringContaining("property fproduct should not exist")]);
    } finally {
      await archiveQuietly("reports", [unfiltered, filtered]);
    }
  });

  tc("TC-RPT-003", async ({ page }) => {
    const manager = await apiAs("salesManager");
    const report = await reportNamed(manager, PIPELINE);
    const table = await tableOf(manager, report.id);
    expect(table.rows.length, "precondition: the Pipeline report has data").toBeGreaterThan(0);
    await openReport(page, report.id, PIPELINE);
    const { name, body } = await download(page, "Export Excel");
    expect(name, "downloaded file name (the client names it reports-<id>)").toBe(`reports-${report.id}.csv`);
    const lines = parseCsv(body.toString("utf8"));
    expect(lines[0], "header row = the on-screen column labels").toEqual(table.columns.map((c) => c.label));
    expect(lines.length - 1, "one line per on-screen row").toBe(table.rows.length);
    // the same rows and columns as on screen: every cell of every row
    expect(lines.slice(1), "all rows").toEqual(table.rows.map((r) => table.columns.map((c) => String(r[c.key]))));
    await expect(bodyRows(page), "on-screen rows (+ totals row)").toHaveCount(table.rows.length + 1);
  });

  tc("TC-RPT-004", async ({ page }) => {
    const manager = await apiAs("salesManager");
    const filters = { dateRange: "This quarter", region: "West" };
    const id = await newReport(manager, PIPELINE, filters);
    try {
      const table = await tableOf(manager, id);
      expect(table.rows.length, "precondition: the report has data").toBeGreaterThan(0);
      await openReport(page, id, PIPELINE);
      const { name, body } = await download(page, "Export PDF");
      expect(name, "downloaded file name (the client names it reports-<id>)").toBe(`reports-${id}.pdf`);
      expect(body.subarray(0, 5).toString("latin1"), "a real PDF").toBe("%PDF-");
      const text = pdfText(body);
      expect(text, "title").toContain(PIPELINE);
      for (const c of table.columns) expect(text, `table header '${c.label}'`).toContain(c.label);
      expect(text, "first stage row").toContain(String(table.rows[0]?.stage));
      // Spec: the PDF shows the title, the filters and the table. The generator prints the title and the run date only (D-120).
      await knownDefect(test.info(), "D-120", async () => {
        expect(text, "the report's filters (region West / date range This quarter) appear in the PDF").toContain("West");
      });
    } finally {
      await archiveQuietly("reports", [id]);
    }
  });

  tc("TC-RPT-006", async () => {
    const manager = await apiAs("salesManager");
    const recipient = `${uniqueTag("RPT6").toLowerCase()}@e2e-mfg.example`; // inert: the E2E backend has no SES key (guarded above)
    const id = await newReport(manager, PIPELINE, { scheduleFrequency: "Daily", sendAt: "08:00", recipients: recipient, format: "PDF" });
    try {
      // Preconditions (plain Errors): the schedule settings were saved.
      const saved = ok(await manager.get(`/modules/reports/${id}`), "read report").body as Rec;
      if (saved.scheduleFrequency !== "Daily" || saved.recipients !== recipient) throw new Error(`precondition: schedule settings not saved (${String(saved.scheduleFrequency)} / ${String(saved.recipients)})`);
      // Spec: the system runs the schedule and delivers the report to the recipients -> a delivery / job record exists. Nothing reads scheduleFrequency
      // (mfg-reports has no mailer, cron or queue), so no ReportSchedule row ever appears.
      // The poll only waits (expect.poll's own timeout error carries no matcherResult, so tc() would read it as a setup error); the final check is a plain expect().
      try {
        // the catch only keeps the wait from throwing; the plain expect() below decides
        await expect.poll(async () => (await reportScheduleRows(id)).length, { timeout: 20_000, intervals: [2_000] }).toBeGreaterThan(0);
      } catch {
        // gap: nothing is recorded; asserted just below
      }
      expect((await reportScheduleRows(id)).length, "a scheduled run (ReportSchedule row) is recorded for a Daily report").toBeGreaterThan(0);
      expect((await reportScheduleRows(id)).map((r) => r.recipientsSentTo), "delivered to the configured recipients only").toEqual([recipient]);
    } finally {
      await archiveQuietly("reports", [id]);
    }
  });

  tc("TC-RPT-009", async ({ page }) => {
    const manager = await apiAs("salesManager");
    // The filters cannot narrow a report (D-118), so the 'impossible filter' state is reached with a seeded report that has no rows.
    let empty: ReportRow | undefined;
    for (const r of await reportsOf(manager)) {
      if ((await tableOf(manager, r.id)).rows.length === 0) {
        empty = r;
        break;
      }
    }
    if (!empty) throw new Error("precondition: at least one seeded report has no rows in the E2E org");
    const columns = (await tableOf(manager, empty.id)).columns;
    await openReport(page, empty.id, empty.name);
    await expect(page.getByText("No data yet."), "'No data' state").toBeVisible();
    await expect(page.getByText("Couldn't load this table.")).toHaveCount(0);
    // export still works and gives an empty file: the header row only
    const csv = await download(page, "Export Excel");
    expect(parseCsv(csv.body.toString("utf8")), "empty CSV = header row only").toEqual([columns.map((c) => c.label)]);
    const pdf = await download(page, "Export PDF");
    expect(pdf.body.subarray(0, 5).toString("latin1"), "empty PDF is still a PDF").toBe("%PDF-");
    expect(pdfText(pdf.body)).toContain(empty.name);
  });
});

test.describe("Reports - Sales Executive", () => {
  test.use({ storageState: authFile("salesExec1") });

  tc("TC-RPT-005", async ({ page }) => {
    const rep = await apiAs("salesExec1");
    const commercial = await apiAs("commercial");
    const director = await apiAs("director");
    // (1) Field-level security of an export: 'Standard cost' / 'Minimum selling price' are restricted for the Sales Executive role.
    expect(await restrictedRolesOf(MFG_USERS.salesExec1.email, "products", "Standard cost"), "precondition: Standard cost is restricted for Sales Executive").toContain("SALES_EXECUTIVE");
    const product = await build.product(commercial, { cost: 640_000, minPrice: 910_000 });
    try {
      const asCommercial = await raw(commercial, `/modules/products/export?search=${product.sku}`);
      const asRep = await raw(rep, `/modules/products/export?search=${product.sku}`);
      expect(asCommercial.status).toBe(200);
      expect(asRep.status, "a Sales Executive may export the products list").toBe(200);
      expect(asCommercial.text, "control: the cost is in Commercial's export").toContain("640000");
      expect(asRep.text, "the restricted values are not in the file").not.toContain("640000");
      expect(asRep.text).not.toContain("910000");
      // Spec: restricted columns are ABSENT from the file; the header still lists them (empty cells) [D-123].
      const header = parseCsv(asRep.text)[0] ?? [];
      await knownDefect(test.info(), "D-123", async () => {
        expect(header, "export header has no cost / minPrice column").not.toEqual(expect.arrayContaining(["cost"]));
        expect(header).not.toEqual(expect.arrayContaining(["minPrice"]));
      });
    } finally {
      await archiveQuietly("products", [product.id]);
    }

    // (2) The module export permission (E flag): Sales Executive holds Reports 'RE' but only 'CRU' on accounts: no E. The export route only checks read (D-1).
    const accountsExport = await raw(rep, "/modules/accounts/export");
    await knownDefect(test.info(), "D-1", async () => {
      expect(accountsExport.status, "export of a module without the E flag").toBe(403);
    });

    // (3) Reports: Sales Executive has Reports 'RE', yet the seeded reports are not visible to the role (own-record scope, seeded reports have no owner) [D-121].
    const visible = await reportsOf(rep);
    await page.goto("/reports");
    await expect(page.getByRole("heading", { name: "Reports", exact: true }).first()).toBeVisible();
    await knownDefect(test.info(), "D-121", async () => {
      expect(visible.map((r) => r.name).sort(), "reports a Sales Executive may open and export").toEqual([...seededNames()].sort());
    });
    const pipeline = await reportNamed(director, PIPELINE);
    const direct = await raw(rep, `/modules/reports/${pipeline.id}/csv`);
    await knownDefect(test.info(), "D-121", async () => {
      expect(direct.status, "report CSV export as Sales Executive").toBe(200);
    });
    if (direct.status !== 200) expect(direct.status, "current: the report is 404 for the role (remove with D-121)").toBe(404);
  });

  tc("TC-RPT-008", async ({ page }) => {
    const manager = await apiAs("salesManager");
    const rep1 = await apiAs("salesExec1");
    const rep2 = await apiAs("salesExec2");
    const director = await apiAs("director");
    const mine = await newReport(manager, PIPELINE, { ownerId: await userIdOf(rep1) }); // throwaway report owned by rep 1 (the seeded ones are invisible to the role, D-121)
    const opps: string[] = [];
    try {
      // Rep 2 owns a deal that rep 1 must not see in a rep-scoped report.
      const account = await build.account(rep2);
      opps.push((await build.opportunity(rep2, account.id, { value: 4_000_000, title: `${uniqueTag("RPT8")} rep2 deal` })).id);
      expect((await reportsOf(rep1)).map((r) => r.id), "rep 1 sees the report it owns").toContain(mine);
      const ownPipeline = (ok(await rep1.get("/mfg-dashboard/team"), "rep 1 pipeline").body as unknown as { kpis: { activePipeline: number } }).kpis.activePipeline;
      const orgPipeline = (await tableOf(director, mine)).totals?.value;
      const asRep1 = await tableOf(rep1, mine);
      expect(asRep1.totals?.value, "the report runs for the rep").toEqual(expect.any(Number));
      // Spec: a rep sees only own data. The report is generated from the whole org: rep 1's report total equals the org total, not the rep's own pipeline (D-122).
      await knownDefect(test.info(), "D-122", async () => {
        expect(asRep1.totals?.value, "rep 1's Pipeline report total = rep 1's own open pipeline").toBe(ownPipeline);
      });
      if (asRep1.totals?.value !== ownPipeline) expect(asRep1.totals?.value, "current: the org-wide total (remove with D-122)").toBe(orgPipeline);
      expect(ownPipeline, "control: rep 1's own pipeline is smaller than the org's").toBeLessThan(orgPipeline ?? 0);
      await openReport(page, mine, PIPELINE);
    } finally {
      await archiveQuietly("reports", [mine]);
      await archiveQuietly("opps", opps);
    }
  });
});
